-- UST Campus Store case study (CSELEC1C). Practice data, not real sales.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
-- Session 2, step 2 (SCD Type 2).
-- On May 15, 2026 the store changed some prices and added products.
-- The source keeps only the CURRENT price: src.products is updated in place.
-- Sales of May 15 and 16 are added to src.sales (table access is back).

BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM src.products WHERE updated_at >= '2026-05-15') THEN
  RAISE EXCEPTION 'This file was already applied.'; END IF; END $$;

UPDATE src.products SET unit_price = '95.00', updated_at = '2026-05-15 06:00:00' WHERE upper(trim(product_code)) = 'CN-0001';
UPDATE src.products SET unit_price = '25.00', updated_at = '2026-05-15 06:00:00' WHERE upper(trim(product_code)) = 'CN-0012';
UPDATE src.products SET unit_price = '380.00', updated_at = '2026-05-15 06:00:00' WHERE upper(trim(product_code)) = 'BK-0003';

COPY src.products (product_code, product_name, category, unit_price, is_active, updated_at) FROM stdin WITH (FORMAT csv);
